"""Entry point."""
import logging

from src import handlers  # noqa: F401

log = logging.getLogger(__name__)


class Reporter:
    def __init__(self, printer):
        self.printer = printer

    def report(self, rows):
        self.printer.print(rows)


def main():
    log.info("starting")
    print("starting on port", 8000)


if __name__ == "__main__":
    main()
